}

import { z } from "zod";

const ServerEnvSchema = z.object({
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  PORT: z.coerce.number().int().min(1).max(65535).default(4000),
  ANTHROPIC_API_KEY: z.string().min(1),
  TUTOR_MODEL: z.string().default("claude-sonnet-4-5"),
  DATABASE_URL: z.url(),
  REDIS_URL: z.string().default(""),
});

export type ServerEnv = z.infer<typeof ServerEnvSchema>;

export function loadServerEnv(source: NodeJS.ProcessEnv = process.env): ServerEnv {
  const parsed = ServerEnvSchema.safeParse(source);
  if (!parsed.success) {
    const detail = parsed.error.issues
      .map((i) => `  - ${i.path.join(".") || "(root)"}: ${i.message}`)
      .join("\n");
    throw new Error(`Invalid environment configuration:\n${detail}`);
  }
  return parsed.data;
}

export type SessionState =
  | { phase: "idle" }
  | { phase: "awaiting_input" }
  | { phase: "thinking"; startedAt: number }
  | { phase: "streaming"; chars: number }
  | { phase: "failed"; reason: string };

export type SessionEvent =
  | { type: "start" }
  | { type: "submit" }
  | { type: "first_token" }
  | { type: "done" }
  | { type: "error"; reason: string };

export function reduce(state: SessionState, event: SessionEvent): SessionState {
  switch (event.type) {
    case "start": return { phase: "awaiting_input" };
    case "submit": return { phase: "thinking", startedAt: 0 };
    case "first_token":
      return state.phase === "thinking" ? { phase: "streaming", chars: 0 } : state;
    case "done": return { phase: "awaiting_input" };
    case "error": return { phase: "failed", reason: event.reason };
  }
}

it("ignora first_token fora de thinking", () => {
  const idle: SessionState = { phase: "idle" };
  expect(reduce(idle, { type: "first_token" })).toBe(idle);
});
